{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "A weighting parameter that linearly combines model-based and model-free Q-values for stage 1 action selection.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A perseveration mechanism that increases the probability of repeating the previous trial's stage 1 choice.",
      "params": [
        {
          "name": "rho",
          "bounds": [0, 10]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\n        if last_action != -1:\n            stickiness[last_action] = 1.0\n            \n        exp_q1 = np.exp(beta * q_stage1_net + rho * stickiness)",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "An eligibility trace that updates the stage 1 model-free Q-value based on the stage 2 reward prediction error.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
